<?phpif (!defined('BASEPATH')) exit('No direct script access allowed');class merteammodel extends CI_Model {    public function getInfo($VarStatus = '', $VarTeamId, $VarCompanyId = '',$VarMerchantId='') {        /*$this->db->select('merchantid,teamid')->from(KN_MERCHANT_TEAM)->join(KN_USERS);        if ($VarStatus <> '') {            //$this->db->where_in('status', array($VarStatus));        } else {            //$this->db->where_in('status', array(1, 2));        }        if (empty($VarTeamId)) {            $ArrWhere['teamid'] = 0;        }        if ($VarCompanyId <> '') {            $ArrWhere['companyid'] = $VarCompanyId;        }        if (!empty($ArrWhere)) {            $this->db->where($ArrWhere);        }        $ArrResultList = $this->db->get()->result_array();        return $ArrResultList;*/        $VarSelect = 'u.id,u.contactname,u.username,mobile,status,desgn,teamid';        $ArrWhere = array(); $VarWhere = '';        $ArrWhere[] = "u.usertype = ".$this->merusertype;        if ($VarTeamId <> '') {            $ArrWhere[] = "teamid = " . $VarTeamId;        }        if ($VarCompanyId <> '') {            $ArrWhere[] = "u.companyid = " . $VarCompanyId;        }        if ($VarMerchantId <> '') {            $ArrWhere[] = "merchantid = " . $VarMerchantId;        }        if(!empty($ArrWhere)) {            $VarWhere = ' WHERE ' . implode(" and ", $ArrWhere);        }        $VarSql = "SELECT ".$VarSelect." FROM ".KN_MERCHANT_TEAM." AS t INNER JOIN ".KN_USERS." AS u ON u.id = t.merchantid         INNER JOIN ".KN_USER_DESGN." AS d ON d.designationid = u.desgnid ". $VarWhere;        return $this->db->query($VarSql)->result_array();    }    public function saveTeamMates($VarTeamId,$ArrMerchantId,$ArrMerchantRemId) {        foreach ($ArrMerchantId as $merchant) {            //echo '<pre>'; print_r($merchant);            $this->db->where('merchantid',$merchant)->update(KN_MERCHANT_TEAM,array('teamid'=>$VarTeamId));        }        foreach ($ArrMerchantRemId as $remMerchant) {            $this->db->where('merchantid',$remMerchant)->update(KN_MERCHANT_TEAM,array('teamid'=>0));        }        $ArrResult['errCode'] = 1;        $ArrResult['msg'] = '';        $ArrResult['id'] = $VarTeamId;        $ArrResult['eid'] = urlencode(base64_encode($VarTeamId));        return $ArrResult;    }    public function teamInfo($VarMerchantId) {        $VarSql = "SELECT u.id,u.contactname,u.username,mobile,teamid FROM ".KN_MERCHANT_TEAM." AS t         INNER JOIN ".KN_USERS." AS u ON u.id = t.merchantid WHERE u.id = ".$VarMerchantId;        return $this->db->query($VarSql)->result_array();    }}